DO $$
BEGIN
  UPDATE articles SET status_tier = 'featured' WHERE view_count >= 10000 AND editor_approved = true;
  UPDATE articles SET status_tier = 'popular' WHERE view_count >= 5000 AND view_count < 10000 AND status_tier IS NULL;
  UPDATE articles SET bonus_points = comment_count * 5 WHERE status_tier = 'featured';
  UPDATE articles SET bonus_points = comment_count * 2 WHERE status_tier = 'popular';
END $$;
SELECT * FROM articles ORDER BY article_id;
